<?php
declare(strict_types=1);
namespace Annam;
/** Reviewed owner snapshot. Never scrapes or guesses recurring availability. */
final class CatalogSync {
    private array $data,$source,$report,$categories=[];
    private const PARENTS=['Murukku'=>'Pakshanams','Mixture'=>'Pakshanams','Chips'=>'Pakshanams','Thattai'=>'Pakshanams','Halwa'=>'Sweets','Kitchen Podis'=>'Podi','Rice Mix Podi'=>'Podi','Rice Mix Herbal Podi'=>'Podi','Rasam Paste'=>'Pickles','Rice Mix Paste'=>'Pickles','Diwali Combos'=>'Diwali 2026','Diwali Sweets'=>'Diwali 2026','Diwali Karams'=>'Diwali 2026'];
    private const ALIASES=['Ulundhu Appalam - Jeera'=>['Ulundhu Applam- Jeera'],'Karuppu Ellu Idly Podi'=>['Karuppu Elllu Idly Podi'],'Wheat Rava Uppma Mix'=>['Wheat Rava Uppum Mix'],'Multigrain Millet Dosa Mix'=>['Multi Grain Millet Dosa Mix'],'Idly with Vadai'=>['Idly With Vadai'],'Chapathi (1)'=>['Chapapthi (1)']];
    public function __construct(private Store $store){$this->data=json_decode(file_get_contents(ANNAM_ROOT.'/resources/catalog-sync.json'),true,512,JSON_THROW_ON_ERROR);$this->source=json_decode(file_get_contents(ANNAM_ROOT.'/resources/source-catalog.json'),true,512,JSON_THROW_ON_ERROR);$this->report=['created'=>[],'updated'=>[],'review'=>[],'menus'=>[],'source'=>$this->data['source']];}
    public static function normal(string $name):string {
        $name=preg_replace('/^\d{1,2}(?:st|nd|rd|th|tth)\s+/i','',$name);$name=preg_replace('/^(?:Bf|Dr)\s*-?\s+/i','',$name);$name=preg_replace('/^Sing(?:le|el) Pack\s*-\s*/i','',$name);
        if(in_array(strtolower($name),['with rice','without rice'],true))$name='Full meals '.$name;
        return preg_replace('/[^a-z0-9]/','',str_replace(['spl ','pakshanms','chapapthi','mixutre','leavs','pck','hawa','vegitable','uppma'],['special ','pakshanams','chapathi','mixture','leaves','pack','halwa','vegetable','uppuma'],strtolower($name)));
    }
    private static function slug(string $name):string{return trim(preg_replace('/[^a-z0-9]+/','-',strtolower($name)),'-');}
    private function category(string $name):int {
        if(isset($this->categories[$name]))return $this->categories[$name];$matches=array_values(array_filter($this->store->categories(),fn($c)=>self::normal($c['name'])===self::normal($name)));if(count($matches)>1)throw new HttpError(422,'Ambiguous category: '.$name);
        $parent=isset(self::PARENTS[$name])?$this->category(self::PARENTS[$name]):null;$id=$matches?(int)$matches[0]['id']:(new Resources($this->store))->save('categories',null,['name'=>$name,'slug'=>self::slug($name),'active'=>'1','sort'=>0]);
        if($parent)$this->store->db->rows('UPDATE catalog_menucategory SET parent_id=? WHERE tenant_id=? AND id=?',[$parent,$this->store->id(),$id]);
        if($name==='Diwali 2026')$this->store->db->rows('UPDATE catalog_menucategory SET description=? WHERE tenant_id=? AND id=?',['Diwali 2026 sweets & pakshanams. Delivery on 5 November and 7 November 2026.',$this->store->id(),$id]);return $this->categories[$name]=$id;
    }
    private function find(string $name,string $kind='courier',?array $slot=null):?array {
        $names=array_map([self::class,'normal'],[$name,...(self::ALIASES[$name]??[])]);$ids=[];foreach($this->source['products'] as $r)if(in_array(self::normal($r['name']),$names,true))$ids[]=(string)$r['source_id'];
        $matches=array_values(array_filter($this->store->items($kind),fn($i)=>in_array(self::normal($i['name']),$names,true)||in_array($i['retailer_id'],$ids,true)));
        if($slot&&count($matches)>1){$assigned=array_column($this->store->db->rows('SELECT item_id FROM catalog_menuschedule WHERE tenant_id=? AND slot_id=?',[$this->store->id(),$slot['id']]),'item_id');$filtered=array_values(array_filter($matches,fn($i)=>in_array($i['id'],$assigned)||str_contains(strtolower($i['category_name']??''),$slot['key'])));if($filtered)$matches=$filtered;}
        if($slot&&count($matches)>1&&count(array_unique(array_map(fn($i)=>self::normal($i['name']).':'.$i['price'],$matches)))===1){usort($matches,fn($a,$b)=>[!$a['active'],$a['id']]<=>[!$b['active'],$b['id']]);$matches=[$matches[0]];}
        if(count($matches)>1)throw new HttpError(422,'Ambiguous product: '.$name.'. Choose exact IDs before syncing.');return $matches[0]??null;
    }
    private function note(array $item,string $text):void {if(!str_contains($item['admin_notes'],$text))$this->store->db->rows('UPDATE catalog_menuitem SET admin_notes=? WHERE tenant_id=? AND id=?',[trim($item['admin_notes']."\n".$text),$this->store->id(),$item['id']]);}
    private function product(array $row,bool $stock,string $kind='courier',?array $slot=null):array {
        $item=$this->find($row['name'],$kind,$slot);$created=!$item;
        if(!$item){$id=(new Resources($this->store))->save('dishes',null,['name'=>$row['name'],'price'=>$row['price'],'fulfilment'=>$kind,'active'=>'1','in_stock'=>$stock?'1':'','is_veg'=>'1']);$item=$this->store->item($id);$key='sync:'.$this->data['version'].':'.$kind.':'.($slot['key']??'').':'.self::slug($row['name']);$this->store->db->rows('UPDATE catalog_menuitem SET retailer_id=? WHERE tenant_id=? AND id=?',[substr(hash('sha256',$key),0,60),$this->store->id(),$id]);$this->note($item,'Needs photo and weight — imported from owner comparison on 30 Oct 2026.');$item=$this->store->item($id);}
        $category=$item['category_id'];if($kind==='courier'){$target=$this->category($row['category']);if(!$category||!in_array((int)$category,$this->store->family($target),true))$category=$target;}
        $this->store->db->rows('UPDATE catalog_menuitem SET active=TRUE,in_stock=?,category_id=?,price=? WHERE tenant_id=? AND id=?',[$stock,$category,$kind==='courier'?$row['price']:$item['price'],$this->store->id(),$item['id']]);
        $missing=[];if(!$item['image'])$missing[]='photo';if(!$item['weight'])$missing[]='weight';if($missing)$this->note($this->store->item((int)$item['id']),'Needs '.implode(' and ',$missing).' — verify before completing catalog details.');$this->report[$created?'created':'updated'][]=$item['name'];return $this->store->item((int)$item['id']);
    }
    public function run(bool $apply=false):array {
        $raw=file_get_contents(ANNAM_ROOT.'/resources/catalog-sync.json');$digest=hash('sha256',$raw);$version=$this->data['version'];if($this->store->tenant['slug']!==$this->data['tenant_slug'])throw new HttpError(422,'This snapshot is only for the configured Annam store.');
        $result=null;
        try{$this->store->db->transaction(function()use($apply,$digest,$version,&$result){$this->store->lock();$previous=$this->store->db->one('SELECT * FROM catalog_catalogsyncrun WHERE tenant_id=? AND version=?',[$this->store->id(),$version]);if($previous){if($previous['digest']!==$digest)throw new HttpError(409,'Applied manifest cannot be changed.');$result=['already_applied'=>true,'version'=>$version];return;}
            foreach(self::PARENTS as $name=>$parent)$this->category($name);
            foreach(['in_stock'=>true,'diwali'=>true,'sold_out'=>false] as $group=>$stock)foreach($this->data[$group] as $row)$this->product($row,$stock);
            foreach($this->data['price_updates'] as $row){$item=$this->find($row['name'])??throw new HttpError(422,'Price product missing: '.$row['name']);if($row['needs_confirmation']){$this->note($item,'Owner decision: verify pack size before changing price to ₹'.$row['price'].'. Current price preserved.');$this->report['review'][]=$row['name'];}else $this->store->db->rows('UPDATE catalog_menuitem SET price=? WHERE tenant_id=? AND id=?',[$row['price'],$this->store->id(),$item['id']]);}
            foreach($this->data['stock_off'] as $name){$item=$this->find($name)??throw new HttpError(422,'Stock product missing: '.$name);$this->store->db->rows('UPDATE catalog_menuitem SET in_stock=FALSE WHERE tenant_id=? AND id=?',[$this->store->id(),$item['id']]);}
            foreach($this->data['build_only'] as $name){$item=$this->find($name);if($item)$this->note($item,'Build only — owner must confirm whether to keep or remove. No removal performed.');$this->report['review'][]=$name;}
            $sourceGroups=[];foreach($this->source['categories'] as $row)foreach(self::PARENTS as $name=>$parent)if(!str_starts_with($name,'Diwali ')&&self::normal($name)===self::normal($row['name']))$sourceGroups[$row['slug']]=[$this->category($name),$this->category($parent)];
            $items=[];foreach($this->store->items('courier') as $i)$items[$i['retailer_id']]=$i;foreach($this->source['products'] as $row)if($i=$items[(string)$row['source_id']]??null)foreach($row['categories']??[] as $slug)if(isset($sourceGroups[$slug])&&(int)$i['category_id']===$sourceGroups[$slug][1]){$this->store->db->rows('UPDATE catalog_menuitem SET category_id=? WHERE tenant_id=? AND id=?',[$sourceGroups[$slug][0],$this->store->id(),$i['id']]);break;}
            foreach($this->data['featured'] as $name){$item=$this->find($name)??throw new HttpError(422,'Featured product missing: '.$name);$tags=json_decode($item['tags'],true);$tags[]= 'featured';$this->store->db->rows('UPDATE catalog_menuitem SET tags=? WHERE tenant_id=? AND id=?',[json_encode(array_values(array_unique($tags))),$this->store->id(),$item['id']]);}
            $banners=$this->store->db->rows("SELECT id FROM content_banner WHERE tenant_id=? AND title ILIKE '%diwali%'",[$this->store->id()]);if(!$banners)(new Resources($this->store))->save('banners',null,['title'=>'Diwali 2026 sweets & pakshanams','subtitle'=>'Delivery on 5 Nov and 7 Nov 2026','link'=>'/shop/diwali-2026/','active'=>'1']);else $this->store->db->rows("UPDATE content_banner SET link='/shop/diwali-2026/' WHERE tenant_id=? AND title ILIKE '%diwali%'",[$this->store->id()]);
            $date=$this->data['daily_menu']['date'];if($date<date('Y-m-d'))$this->report['review'][]='Past dated menu preserved: '.$date;else foreach($this->data['daily_menu']['slots'] as $key=>$rows){$slot=$this->store->db->one('SELECT * FROM catalog_slot WHERE tenant_id=? AND key=?',[$this->store->id(),$key]);if(!$slot){$id=(new Resources($this->store))->save('slots',null,['key'=>$key,'label'=>ucfirst($key),'order_cutoff'=>'23:59:59','active'=>'1']);$slot=$this->store->slot($id);}if($this->store->db->one('SELECT id FROM catalog_menuday WHERE tenant_id=? AND slot_id=? AND on_date=?',[$this->store->id(),$slot['id'],$date])){$this->report['review'][]='Staff menu preserved: '.$key;continue;}$ids=[];foreach($rows as $row){$item=$this->product($row,true,'scheduled',$slot);$ids[]=$item['id'];}$this->store->saveMenu($date,(int)$slot['id'],$ids,0);foreach($rows as $n=>$row)$this->store->db->rows("UPDATE catalog_menuschedule SET price_override=? WHERE tenant_id=? AND slot_id=? AND on_date=? AND item_id=? AND mode='date'",[$row['price'],$this->store->id(),$slot['id'],$date,$ids[$n]]);$this->report['menus'][]=$key;}
            foreach($this->data['daily_review'] as $name)foreach($this->store->items('scheduled') as $i)if(self::normal($i['name'])===self::normal($name))$this->note($i,'Owner decision: build-only daily dish; recurring availability unchanged.');
            $result=['already_applied'=>false,'applied'=>$apply,'version'=>$version,'report'=>$this->report];if(!$apply)throw new \LogicException('dry-run rollback');$this->store->db->rows('INSERT INTO catalog_catalogsyncrun(tenant_id,version,digest,report,applied_at) VALUES(?,?,?,?,CURRENT_TIMESTAMP)',[$this->store->id(),$version,$digest,json_encode($this->report,JSON_THROW_ON_ERROR)]);
        });}catch(\LogicException $e){if($e->getMessage()!=='dry-run rollback')throw $e;}return $result;
    }
}
